#import "../App/AI/Providers/TFAIProtocol.h"
static int count=0,failed=0;
static void Check(BOOL ok,NSString *s){count++;if(!ok)failed++;printf("%s %s\n",ok?"PASS":"FAIL",s.UTF8String);}
int main(int argc,char **argv){@autoreleasepool{NSString *root=@(argv[1]);NSError *error=nil;
for(NSString *scheme in @[@"rootful",@"rootless",@"roothide"]){NSString *path=[root stringByAppendingPathComponent:[scheme stringByAppendingPathExtension:@"deb"]];NSData *data=[NSData dataWithContentsOfFile:path];NSDictionary *v=TFAIInspectArtifact(data,path,&error);Check(v!=nil,[scheme stringByAppendingString:@" parsed"]);NSString *arch=@{@"rootful":@"iphoneos-arm",@"rootless":@"iphoneos-arm64",@"roothide":@"iphoneos-arm64e"}[scheme];Check([v[@"controlFields"][@"Architecture"] isEqual:arch],@"control architecture comes from package bytes");Check([v[@"dylibs"][0][@"path"] hasPrefix:[scheme isEqual:@"rootless"]?@"./var/jb/":@"./Library/"],@"actual install path distinguishes schemes");Check([v[@"dylibs"][0][@"slices"][0][@"cpu"] isEqual:@"arm64"],@"CPU reported independently from package architecture");NSArray *entries=TFAIStageAttachmentFiles(root,@[path.lastPathComponent],@"产物测试",&error);Check(entries.count==1&&[entries[0][@"artifactInspection"] boolValue],@"binary stages as local inspection reference");NSDictionary *resolved=TFAIResolveAttachments(entries,&error).firstObject;Check([resolved[@"kind"] isEqual:@"text"]&&[resolved[@"content"] containsString:arch],@"binary bytes never sent as model text/image");NSDictionary *read=TFAIReadAttachmentReferences(@{@"fixture":resolved},@{@"id":@"fixture",@"line_count":@120},&error);Check([read[@"content"] containsString:@"controlFields"],@"read_attachment accesses decoded control and Mach-O evidence");NSString *stored=TFAIAttachmentLocalPath(entries.firstObject,nil);if(stored)[NSFileManager.defaultManager removeItemAtPath:stored error:nil];}
Check(!TFAIInspectArtifact([@"broken" dataUsingEncoding:NSUTF8StringEncoding],@"bad.deb",&error),@"malformed package rejected");
Check(!TFAIInspectArtifact([NSMutableData dataWithLength:32],@"bad.dylib",&error),@"invalid Mach-O rejected");
NSArray *candidates=TFAIAttachmentCandidates(root,&error);Check(candidates.count==3,@"all three artifacts appear in file picker candidates");
NSDictionary *record=@{@"name":@"read_project_config",@"status":@"completed",@"result":@{@"optimization":@"-O2",@"sources":@[@"Tweak.xm"],@"sha256":@"hidden-digest"}};NSString *detail=TFAIActivityDetail(record);Check([detail containsString:@"优化方案：-O2"]&&![detail containsString:@"hidden-digest"]&&![detail containsString:@"{"],@"tool activity renders labeled fields instead of raw JSON");Check([TFAIActivityTitle(record) containsString:@"读取项目配置"],@"activity uses actual tool action title");
NSMutableArray *events=[NSMutableArray new];TFAIStreamDecoder *d=[[TFAIStreamDecoder alloc]initWithProtocol:@"responses" event:^(NSDictionary *e){[events addObject:e];}];[d acceptJSON:@{@"type":@"response.reasoning_summary_text.delta",@"item_id":@"r1",@"delta":@"Published summary"}];[d acceptJSON:@{@"type":@"response.output_item.done",@"item":@{@"type":@"reasoning",@"id":@"r1",@"summary":@[@{@"type":@"summary_text",@"text":@"Published summary"}],@"encrypted_content":@"never-display"}}];NSArray *summaries=[events filteredArrayUsingPredicate:[NSPredicate predicateWithFormat:@"type == %@",@"analysis_summary"]];Check(summaries.count==1&&[summaries[0][@"text"] isEqual:@"Published summary"],@"streamed published summary deduplicates final item and hides encryption");
for(NSString *proto in @[@"chat",@"anthropic",@"gemini"]){[events removeAllObjects];d=[[TFAIStreamDecoder alloc]initWithProtocol:proto event:^(NSDictionary *e){[events addObject:e];}];NSDictionary *payload=[proto isEqual:@"chat"]?@{@"choices":@[@{@"message":@{@"role":@"assistant",@"reasoning_content":@"Visible summary",@"content":@"Answer"},@"finish_reason":@"stop"}]}:[proto isEqual:@"anthropic"]?@{@"type":@"message",@"content":@[@{@"type":@"thinking",@"thinking":@"Visible summary"},@{@"type":@"text",@"text":@"Answer"}],@"stop_reason":@"end_turn"}:@{@"candidates":@[@{@"content":@{@"parts":@[@{@"thought":@YES,@"text":@"Visible summary"},@{@"text":@"Answer"}]},@"finishReason":@"STOP"}]};[d acceptJSON:payload];Check([[events valueForKey:@"type"] containsObject:@"analysis_summary"],[proto stringByAppendingString:@" exposes provider published thinking separately"]);}
NSDictionary *c=@{@"protocol":@"responses",@"model":@"gpt-5",@"baseURL":@"https://fixture.invalid/v1"};Check([TFAIRequestBody(@[],c,@[],YES,nil)[@"reasoning"][@"summary"] isEqual:@"auto"],@"known reasoning models request published summary");NSMutableDictionary *non=[c mutableCopy];non[@"model"]=@"gpt-4.1";Check(!TFAIRequestBody(@[],non,@[],YES,nil)[@"reasoning"],@"nonreasoning model receives no unsupported reasoning parameter");
printf("RESULT %d checks %d failures\n",count,failed);return failed?1:0;}}
